<template>
  <div class="page-transition space-y-5">
    <header class="flex flex-wrap items-start justify-between gap-4">
      <div>
        <h1 class="text-xl font-bold text-gray-900">业务协作</h1>
        <p class="mt-1 text-sm text-gray-500">只关注我发起、参与或需要我确认的业务需求；项目拆分和技术细节放在详情中。</p>
      </div>
      <div class="flex flex-wrap items-center gap-2">
        <button type="button" class="feishu-btn-primary" @click="openDemandModal"><Lightbulb class="h-4 w-4" /> 提交新需求</button>
        <button type="button" class="feishu-btn-ghost" @click="openMatterModal()"><Plus class="h-4 w-4" /> 补充资料/反馈</button>
        <button type="button" class="feishu-btn-ghost" :disabled="!selectedItem" @click="selectedItem && openActivity(selectedItem)"><MessagesSquare class="h-4 w-4" /> 产品动态</button>
        <button type="button" class="feishu-btn-ghost text-accent-600" @click="load">刷新</button>
      </div>
    </header>

    <section class="grid grid-cols-2 gap-3 lg:grid-cols-4">
      <button v-for="card in summaryCards" :key="card.key" type="button" @click="selectSummary(card)" :class="['rounded-2xl border p-4 text-left transition hover:-translate-y-0.5 hover:shadow-sm', card.className, summaryFocus === card.focus ? 'ring-2 ring-accent-200' : '']">
        <div class="flex items-center justify-between gap-2"><p class="text-xs text-gray-500">{{ card.label }}</p><component :is="card.icon" class="h-4 w-4 opacity-70" /></div>
        <p class="mt-1 text-2xl font-bold tabular-nums" :class="card.valueClass">{{ card.value }}</p>
        <p class="mt-1 text-[11px] text-gray-400">{{ card.desc }}</p>
      </button>
    </section>

    <section class="grid gap-5 xl:grid-cols-[minmax(0,1fr)_360px]">
      <div class="feishu-section min-w-0 overflow-hidden">
        <div class="flex flex-wrap items-center justify-between gap-3 border-b border-gray-100 px-4 py-3">
          <div><h2 class="text-sm font-semibold text-gray-900">{{ activeView === 'all' ? '全部相关事项' : activeView === 'pending' ? '待我处理' : '我的业务需求' }}</h2><p class="mt-1 text-[11px] text-gray-400">业务端只展示需求进度、下一步和待确认事项；项目结构可在详情中查看。</p></div>
          <div class="flex flex-wrap items-center gap-1 rounded-lg bg-gray-50 p-1"><button v-for="tab in viewTabs" :key="tab.key" type="button" :disabled="tab.key === 'all' && !isLeader()" @click="(tab.key !== 'all' || isLeader()) && selectView(tab.key)" :class="['rounded-md px-2.5 py-1.5 text-xs', activeView === tab.key ? 'bg-white font-medium text-accent-600 shadow-sm' : tab.key === 'all' && !isLeader() ? 'cursor-not-allowed text-gray-300' : 'text-gray-500 hover:text-gray-700']">{{ tab.label }}<span v-if="tab.key === 'all' && !isLeader()" class="ml-1 text-[10px]">（授权）</span></button></div>
        </div>
        <div class="flex flex-wrap items-center gap-2 border-b border-gray-100 px-4 py-3"><div class="relative min-w-[220px] flex-1"><Search class="pointer-events-none absolute left-3 top-2.5 h-4 w-4 text-gray-400" /><input v-model="keyword" class="feishu-input w-full pl-9" placeholder="搜索项目、需求或负责人" /></div><select v-model="stageFilter" class="feishu-input w-auto min-w-[150px]"><option value="all">全部阶段</option><option v-for="stage in stageOptions" :key="stage" :value="stage">{{ stage }}</option></select></div>
        <div v-if="loading" class="flex h-64 items-center justify-center text-sm text-gray-400">业务事项加载中...</div>
        <div v-else-if="filteredItems.length === 0" class="px-5 py-16 text-center"><Inbox class="mx-auto h-10 w-10 text-gray-300" /><p class="mt-3 text-sm text-gray-500">当前视图还没有事项</p><p class="mt-1 text-xs text-gray-400">提交新需求后，记录会进入需求池并在这里显示。</p></div>
        <div v-else class="space-y-3 p-3">
          <template v-if="businessView">
            <article v-for="item in filteredItems" :key="item.key" class="rounded-xl border border-slate-200 bg-white p-4 transition hover:border-accent-200 hover:shadow-sm">
              <div class="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
                <button type="button" class="min-w-0 flex-1 text-left" @click="openDetail(item)">
                  <div class="flex flex-wrap items-center gap-2"><span :class="sourceClass(item.sourceType)">{{ item.sourceLabel }}</span><span :class="stageClass(item.stage)">{{ item.stage }}</span><span v-if="item.pendingAction" class="rounded-full bg-amber-50 px-2 py-0.5 text-[10px] font-medium text-amber-700">{{ item.pendingAction }}</span></div>
                  <h3 class="mt-2 truncate text-sm font-semibold text-gray-900">{{ item.title }}</h3>
                  <p class="mt-1 text-xs text-gray-500">{{ item.projectName || item.department || '未归类项目' }} · {{ item.ownerName || '负责人待定' }}</p>
                  <div class="mt-3 flex items-center gap-3"><div class="h-1.5 min-w-0 flex-1 overflow-hidden rounded-full bg-gray-100"><div class="h-full rounded-full bg-accent-500 transition-all" :style="{ width: `${item.progress}%` }" /></div><span class="shrink-0 text-[11px] font-medium text-gray-500">{{ item.progress }}%</span></div>
                  <div class="mt-3 flex flex-wrap items-center gap-x-4 gap-y-1 text-[11px] text-slate-500"><span><b class="font-medium text-slate-600">下一步：</b>{{ businessNextStep(item) }}</span><span v-if="item.expectedDeliveryTime"><b class="font-medium text-slate-600">预计交付：</b>{{ item.expectedDeliveryTime }}</span></div>
                  <p class="mt-2 truncate text-[11px] text-slate-500"><span class="font-medium text-slate-600">最新动态：</span>{{ latestActivityText(item) }}<span v-if="item.feedbackSummary" class="ml-2" :class="item.feedbackTone === 'danger' ? 'text-rose-600' : item.feedbackTone === 'warning' ? 'text-amber-600' : 'text-emerald-600'">{{ item.feedbackSummary }}</span></p>
                </button>
                <div class="flex shrink-0 flex-wrap items-center gap-2 lg:justify-end"><button type="button" class="feishu-btn-ghost text-xs" @click="openDetail(item)">查看详情</button><button type="button" class="feishu-btn-ghost text-xs" :disabled="!activityTarget(item)" @click="openActivity(item)">查看动态</button><button v-if="item.actionLabel" type="button" class="feishu-btn-primary text-xs" @click="runItemAction(item)">{{ item.actionLabel }}</button></div>
              </div>
            </article>
          </template>
          <template v-else>
          <section v-for="group in displayGroups" :key="group.key" class="overflow-hidden rounded-xl border border-slate-200 bg-white">
            <div class="flex items-stretch">
              <button type="button" class="min-w-0 flex-1 px-4 py-3 text-left transition hover:bg-slate-50" @click="toggleGroup(group.key)">
                <div class="flex items-start gap-3">
                  <ChevronRight :class="['mt-1 h-4 w-4 shrink-0 text-slate-400 transition-transform', isGroupExpanded(group.key) ? 'rotate-90' : '']" />
                  <div class="min-w-0 flex-1">
                    <div class="flex flex-wrap items-center gap-2"><span :class="sourceClass(group.header.sourceType)">{{ group.header.sourceLabel }}</span><span :class="stageClass(group.header.stage)">{{ group.header.stage }}</span><span class="text-[11px] text-slate-400">{{ group.children.length }} 个子项</span></div>
                    <h3 class="mt-1 truncate text-sm font-semibold text-gray-900">{{ group.header.title }}</h3>
                    <div class="mt-2 flex items-center gap-3"><div class="h-1.5 min-w-0 flex-1 overflow-hidden rounded-full bg-gray-100"><div class="h-full rounded-full bg-accent-500 transition-all" :style="{ width: `${group.header.progress}%` }" /></div><span class="shrink-0 text-[11px] font-medium text-gray-500">{{ group.header.progress }}%</span></div>
                    <p class="mt-2 truncate text-[11px] text-slate-500"><span class="font-medium text-slate-600">最新动态：</span>{{ latestActivityText(group.header) }}</p>
                  </div>
                </div>
              </button>
              <button v-if="group.header.id && group.header.sourceType === 'project'" type="button" class="mr-3 self-center whitespace-nowrap text-xs font-medium text-accent-600 hover:text-accent-700" @click="openDetail(group.header)">查看 L2</button>
            </div>
            <div v-if="isGroupExpanded(group.key)" class="divide-y divide-slate-100 border-t border-slate-100 bg-slate-50/30">
              <article v-for="item in group.children" :key="item.key" class="px-4 py-3 pl-11 transition hover:bg-white">
                <div class="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
                  <button type="button" class="min-w-0 flex-1 text-left" @click="openDetail(item)">
                    <div class="flex flex-wrap items-center gap-2"><span :class="sourceClass(item.sourceType)">{{ item.sourceLabel }}</span><span :class="stageClass(item.stage)">{{ item.stage }}</span><span v-if="item.pendingAction" class="rounded-full bg-amber-50 px-2 py-0.5 text-[10px] font-medium text-amber-700">{{ item.pendingAction }}</span></div>
                    <h4 class="mt-1.5 truncate text-sm font-semibold text-gray-900">{{ item.title }}</h4>
                    <p class="mt-1 text-xs text-gray-500">{{ item.projectName || item.department || '未归类项目' }} · {{ item.ownerName || '负责人待定' }}<span v-if="item.updatedAt"> · 更新于 {{ formatDate(item.updatedAt) }}</span></p>
                    <div class="mt-2 flex items-center gap-3"><div class="h-1.5 min-w-0 flex-1 overflow-hidden rounded-full bg-gray-100"><div class="h-full rounded-full bg-accent-500 transition-all" :style="{ width: `${item.progress}%` }" /></div><span class="shrink-0 text-[11px] font-medium text-gray-500">{{ item.progress }}%</span></div>
                    <p class="mt-2 truncate text-[11px] text-slate-500"><span class="font-medium text-slate-600">最新动态：</span>{{ latestActivityText(item) }}<span v-if="item.feedbackSummary" class="ml-2" :class="item.feedbackTone === 'danger' ? 'text-rose-600' : item.feedbackTone === 'warning' ? 'text-amber-600' : 'text-emerald-600'">{{ item.feedbackSummary }}</span></p>
                  </button>
                  <div class="flex shrink-0 flex-wrap items-center gap-2 lg:justify-end"><button type="button" class="feishu-btn-ghost text-xs" @click="openDetail(item)">查看详情</button><button type="button" class="feishu-btn-ghost text-xs" :disabled="!activityTarget(item)" @click="openActivity(item)">产品动态</button><button v-if="item.actionLabel" type="button" class="feishu-btn-primary text-xs" @click="runItemAction(item)">{{ item.actionLabel }}</button></div>
                </div>
              </article>
              <p v-if="!group.children.length" class="px-4 py-4 pl-11 text-xs text-slate-400">当前筛选下没有可见子项。</p>
            </div>
          </section>
          </template>
        </div>
      </div>
      <aside class="feishu-section h-fit overflow-hidden"><div class="flex items-center justify-between border-b border-gray-100 px-4 py-3"><div><h2 class="text-sm font-semibold text-gray-900">待我处理</h2><p class="mt-1 text-[11px] text-gray-400">需要业务侧确认或查看的事项。</p></div><span class="rounded-full bg-accent-50 px-2 py-0.5 text-xs font-semibold text-accent-600">{{ pendingItems.length }}</span></div><div v-if="pendingItems.length" class="divide-y divide-gray-100"><button v-for="item in pendingItems.slice(0, 8)" :key="'pending-' + item.key" type="button" class="w-full px-4 py-3 text-left transition hover:bg-gray-50" @click="runItemAction(item)"><div class="flex items-start justify-between gap-2"><span class="truncate text-sm font-semibold text-gray-800">{{ item.title }}</span><ChevronRight class="mt-0.5 h-4 w-4 shrink-0 text-gray-400" /></div><p class="mt-1 text-xs text-gray-500">{{ item.pendingAction }}</p><p class="mt-1 text-[11px] text-gray-400">{{ item.stage }} · {{ item.ownerName || '负责人待定' }}</p></button></div><div v-else class="px-4 py-12 text-center text-xs text-gray-400"><CheckCircle2 class="mx-auto h-8 w-8 text-emerald-300" /><p class="mt-2">当前没有待处理事项</p></div></aside>
    </section>

    <div v-if="modal === 'demand'" class="modal-backdrop" @click.self="closeModal"><div class="modal-card max-w-3xl"><div class="modal-header"><div><p class="text-xs font-semibold text-accent-600">需求池入口</p><h2 class="mt-1 text-lg font-bold text-gray-900">提交新需求</h2><p class="mt-1 text-xs text-gray-500">填写最少必要信息，提交后进入需求池待 IT 初筛。</p></div><button type="button" class="modal-close" @click="closeModal">×</button></div><div class="modal-body" @paste="handlePaste"><div class="grid gap-4 md:grid-cols-2"><label class="block md:col-span-2"><span class="form-label">需求标题 <em>可选</em></span><input v-model="demandForm.title" class="feishu-input w-full" maxlength="300" placeholder="例如：希望在订单列表增加批量导出" /></label><label class="block"><span class="form-label">相关项目 <em>可暂不确定</em></span><select v-model="demandForm.projectId" class="feishu-input w-full"><option value="">暂不确定，提交后由 IT 归类</option><option v-for="project in visibleProjectOptions" :key="project.id" :value="project.id">{{ project.name }}</option></select></label><label class="block"><span class="form-label">归属部门</span><select v-if="departments.length" v-model="demandForm.department" class="feishu-input w-full"><option value="">请选择部门</option><option v-for="department in departments" :key="department" :value="department">{{ department }}</option></select><input v-else v-model="demandForm.department" class="feishu-input w-full" placeholder="例如：电商部" /></label><label class="block"><span class="form-label">业务紧急程度</span><select v-model="demandForm.businessUrgency" class="feishu-input w-full"><option value="urgent">尽快处理</option><option value="planned">计划内处理</option><option value="normal">一般事项</option></select></label><label class="block"><span class="form-label">期望交付时间 <em>可选</em></span><input v-model="demandForm.expectedDeliveryTime" type="date" class="feishu-input w-full" /></label><label class="block md:col-span-2"><span class="form-label">当前问题与期望结果</span><textarea v-model="demandForm.description" rows="5" maxlength="10000" class="feishu-input w-full resize-y" placeholder="请描述背景、现象、期望结果或验收方式；也可以直接粘贴图片" /></label></div><div class="rounded-xl border border-dashed border-gray-200 bg-gray-50/70 p-3"><div class="flex flex-wrap items-center justify-between gap-2"><div><p class="text-xs font-medium text-gray-700">附件</p><p class="mt-1 text-[11px] text-gray-400">支持粘贴板图片和常见文档，单个文件最大 50MB。</p></div><label class="feishu-btn-ghost cursor-pointer text-xs text-accent-600">添加附件<input type="file" class="hidden" multiple accept="image/*,video/*,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.csv,.zip,.rar,.7z" @change="handleFileInput" /></label></div><div v-if="pendingFiles.length" class="mt-3 grid gap-2 sm:grid-cols-2"><div v-for="(file, index) in pendingFiles" :key="file.name + file.size + index" class="flex items-center gap-2 rounded-md border border-gray-200 bg-white px-2.5 py-2"><img v-if="filePreview(file)" :src="filePreview(file)" class="h-9 w-9 rounded object-cover" /><span v-else class="flex h-9 w-9 items-center justify-center rounded bg-gray-100 text-[10px] uppercase text-gray-500">{{ fileExtension(file) || '文件' }}</span><span class="min-w-0 flex-1 truncate text-xs text-gray-600">{{ file.name }}<small class="ml-1 text-gray-400">{{ formatSize(file.size) }}</small></span><button type="button" class="text-gray-400 hover:text-rose-500" @click="removePendingFile(index)">×</button></div></div></div></div><div class="modal-footer"><span class="text-[11px] text-gray-400">提交后记录会保留在需求池，并在“我的事项”中显示。</span><div class="flex gap-2"><button type="button" class="feishu-btn-ghost" @click="closeModal">取消</button><button type="button" class="feishu-btn-primary" :disabled="saving" @click="submitDemand">{{ saving ? '提交中...' : '提交到需求池' }}</button></div></div></div></div>

    <div v-if="modal === 'matter'" class="modal-backdrop" @click.self="closeModal"><div class="modal-card max-w-2xl"><div class="modal-header"><div><p class="text-xs font-semibold text-violet-600">关联已有 L3</p><h2 class="mt-1 text-lg font-bold text-gray-900">补充资料/反馈</h2><p class="mt-1 text-xs text-gray-500">反馈、资料和问题必须挂在已有需求下，避免产生重复记录。</p></div><button type="button" class="modal-close" @click="closeModal">×</button></div><div class="modal-body space-y-4"><label class="block"><span class="form-label">关联 L3 需求 <b>*</b></span><select v-model="matterForm.requirementId" class="feishu-input w-full"><option value="">请选择已有 L3</option><option v-for="item in visibleRequirementOptions" :key="item.id" :value="item.id">{{ item.projectName || item.pname || '未归属项目' }} · {{ item.title }}</option></select></label><div class="grid gap-4 md:grid-cols-2"><label class="block"><span class="form-label">事项类型</span><select v-model="matterForm.kind" class="feishu-input w-full"><option value="resource_request">资料提供</option><option value="clarification">规则确认</option><option value="business_feedback">意见反馈</option><option value="issue">问题反馈</option><option value="acceptance">测试验收</option></select></label><label class="block"><span class="form-label">期望回复时间 <em>可选</em></span><input v-model="matterForm.dueDate" type="date" class="feishu-input w-full" /></label></div><label class="block"><span class="form-label">事项标题 <b>*</b></span><input v-model="matterForm.title" class="feishu-input w-full" maxlength="300" placeholder="例如：请确认本次页面字段范围" /></label><label class="block"><span class="form-label">说明 <b>*</b></span><textarea v-model="matterForm.content" rows="5" class="feishu-input w-full resize-y" placeholder="描述需要 IT 处理、确认或回复的内容" /></label></div><div class="modal-footer"><button type="button" class="feishu-btn-ghost" @click="closeModal">取消</button><button type="button" class="feishu-btn-primary" :disabled="saving" @click="submitMatter">{{ saving ? '提交中...' : '提交事项' }}</button></div></div></div>

